/**
 * trait-network-gemma.js
 * ---------------------------------------------------------------------
 * Interactive trait-correlation network for Gemma-3-1B-It, meant to run
 * as a lead-in before the EFA factor-loadings figure: it shows the same
 * underlying idea (traits cluster/oppose each other in a model's probe
 * space) at the level of individual trait pairs, before EFA compresses
 * that structure into a handful of factors.
 *
 * 24 traits are sampled (3 per SCM-dictionary x valence combination, 8
 * combinations = 24 nodes) and every pairwise Pearson correlation
 * between their raw per-message probe predictions is precomputed by
 * figure_workspace/interactive_figures/build_trait_network_data.py
 * (TRAIT_NETWORK_DATA above; regenerate + re-paste to refresh). All 276
 * pairwise correlations ship with the page; only each node's own
 * strongest few (by |r|) are drawn as edges (TOP_K_EDGES below), so the
 * figure reads as each trait's nearest neighbors rather than a hairball,
 * with no interactive threshold control needed.
 *
 * Layout is a small hand-rolled force simulation (repulsion between all
 * nodes + a spring per drawn edge, pulled shorter the stronger the
 * correlation, plus weak centering) rather than a fixed circular
 * arrangement, so how traits cluster is itself informative. Nodes can
 * also be dragged by hand (Pointer Events, converted from screen space
 * into the SVG's viewBox coordinates via getScreenCTM()); a dragged node
 * is pinned while the rest of the layout keeps reacting to it live. No
 * chart library is used here (plain SVG + rAF), unlike the EFA/trait-
 * performance widgets, since a force layout with drag isn't something
 * Plotly does natively.
 *
 * Node color is the trait's SCM dictionary, using the exact same
 * validated 4-color set as the trait-performance bar chart, for visual
 * continuity across figures. Edge color is the correlation's polarity
 * (a colorblind-safe green/red substitute pair -- see DICT/EDGE color
 * comments below) with a solid/dashed secondary encoding so polarity
 * doesn't rely on hue alone; edge thickness scales linearly with |r|
 * between the min and max |r| among the edges actually drawn.
 */
(function () {
  const el = document.getElementById("trait-network-gemma-canvas");
  if (!el || typeof TRAIT_NETWORK_DATA === "undefined") return;

  const DICT_LABEL = {
    sociability: "Sociability",
    morality: "Morality",
    assertiveness: "Assertiveness",
    ability: "Ability",
  };
  // Same validated 4-color set as trait-performance-llama.js, reused so
  // a dictionary reads as the same color across every figure on the page.
  const DICT_COLOR = {
    sociability: { light: "#2a78d6", dark: "#3987e5" },
    morality: { light: "#eda100", dark: "#c98500" },
    assertiveness: { light: "#e87ba4", dark: "#d55181" },
    ability: { light: "#008300", dark: "#008300" },
  };
  // Vermillion/bluish-green rather than pure red/green -- validated with
  // the dataviz skill's checker (all-pairs CVD ΔE 11.0, normal-vision ΔE
  // 25.8, both surfaces) as a colorblind-safer stand-in for the
  // conventional "red = negative, green = positive" correlation-network
  // convention the user asked for. Solid/dashed stroke is the secondary
  // encoding so polarity is never carried by hue alone.
  const EDGE_COLOR = { pos: "#009E73", neg: "#D55E00" };

  const DICT_ORDER = ["sociability", "morality", "assertiveness", "ability"];

  function cssVar(name) {
    return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  }
  function isDark() {
    return document.documentElement.getAttribute("data-theme") === "dark";
  }
  function dictColor(dict) {
    return DICT_COLOR[dict][isDark() ? "dark" : "light"];
  }

  const svgNS = "http://www.w3.org/2000/svg";
  const W = 900;
  const H = 560;
  const MARGIN = 46;

  el.innerHTML = "";
  const wrap = document.createElement("div");
  wrap.style.width = "100%";
  el.appendChild(wrap);

  const svg = document.createElementNS(svgNS, "svg");
  svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
  svg.setAttribute("width", "100%");
  svg.style.display = "block";
  svg.style.height = "auto";
  wrap.appendChild(svg);

  const edgesLayer = document.createElementNS(svgNS, "g");
  const nodesLayer = document.createElementNS(svgNS, "g");
  const labelsLayer = document.createElementNS(svgNS, "g");
  svg.appendChild(edgesLayer);
  svg.appendChild(nodesLayer);
  svg.appendChild(labelsLayer);

  // Simple tooltip, positioned in screen space (outside the SVG so it
  // never gets clipped/scaled by the viewBox).
  const tooltip = document.createElement("div");
  tooltip.style.cssText =
    "position:absolute;pointer-events:none;z-index:5;opacity:0;transition:opacity .1s ease;" +
    "background:var(--color-ink);color:var(--color-bg);font-family:var(--font-sans);" +
    "font-size:0.78rem;line-height:1.4;padding:0.4em 0.6em;border-radius:4px;max-width:220px;";
  wrap.style.position = "relative";
  wrap.appendChild(tooltip);

  function showTooltip(html, evtX, evtY) {
    tooltip.innerHTML = html;
    const rect = wrap.getBoundingClientRect();
    tooltip.style.left = evtX - rect.left + 14 + "px";
    tooltip.style.top = evtY - rect.top + 10 + "px";
    tooltip.style.opacity = "1";
  }
  function hideTooltip() {
    tooltip.style.opacity = "0";
  }

  // ---- simulation state --------------------------------------------
  const N = TRAIT_NETWORK_DATA.nodes.length;
  const cx = W / 2;
  const cy = H / 2;
  const R = Math.min(W, H) / 2 - MARGIN - 40;
  const nodes = TRAIT_NETWORK_DATA.nodes.map((n, i) => {
    const angle = (2 * Math.PI * i) / N - Math.PI / 2;
    return { ...n, x: cx + R * Math.cos(angle), y: cy + R * Math.sin(angle), vx: 0, vy: 0 };
  });
  const nodeByTerm = Object.fromEntries(nodes.map((n) => [n.term, n]));

  const REPULSION = 5200;
  const SPRING_K = 0.045;
  const CENTER_K = 0.012;
  const DAMPING = 0.82;
  const IDEAL_MAX = 230; // ideal edge length at |r| -> 0
  const IDEAL_MIN = 70; // ideal edge length at |r| -> 1

  function idealLength(r) {
    return IDEAL_MAX - Math.abs(r) * (IDEAL_MAX - IDEAL_MIN);
  }

  // Show, per node, only its TOP_K_EDGES strongest correlations (by |r|),
  // unioned across all nodes -- an edge survives if either endpoint ranks
  // it among their own closest neighbors. Static (computed once from the
  // full 276-edge set), not interactive.
  const TOP_K_EDGES = 5;
  function computeTopKEdges(k) {
    const byTerm = {};
    for (const n of TRAIT_NETWORK_DATA.nodes) byTerm[n.term] = [];
    for (const e of TRAIT_NETWORK_DATA.edges) {
      byTerm[e.source].push(e);
      byTerm[e.target].push(e);
    }
    const seen = new Set();
    const picked = [];
    for (const term of Object.keys(byTerm)) {
      const ranked = byTerm[term].slice().sort((a, b) => Math.abs(b.r) - Math.abs(a.r));
      for (const e of ranked.slice(0, k)) {
        const key = e.source + "|" + e.target;
        if (!seen.has(key)) {
          seen.add(key);
          picked.push(e);
        }
      }
    }
    return picked;
  }
  const visibleEdges = computeTopKEdges(TOP_K_EDGES).map((e) => ({
    ...e,
    s: nodeByTerm[e.source],
    t: nodeByTerm[e.target],
  }));

  // Edge stroke-width scales linearly with |r| between the min and max
  // among the edges actually drawn (not the full correlation range).
  const edgeAbsRs = visibleEdges.map((e) => Math.abs(e.r));
  const MIN_ABS_R = Math.min(...edgeAbsRs);
  const MAX_ABS_R = Math.max(...edgeAbsRs);
  const EDGE_WIDTH_MIN = 1.5;
  const EDGE_WIDTH_MAX = 6;
  function edgeWidth(r) {
    if (MAX_ABS_R === MIN_ABS_R) return (EDGE_WIDTH_MIN + EDGE_WIDTH_MAX) / 2;
    const t = (Math.abs(r) - MIN_ABS_R) / (MAX_ABS_R - MIN_ABS_R);
    return EDGE_WIDTH_MIN + t * (EDGE_WIDTH_MAX - EDGE_WIDTH_MIN);
  }

  function tick() {
    for (const n of nodes) {
      n.fx = 0;
      n.fy = 0;
    }
    for (let i = 0; i < nodes.length; i++) {
      for (let j = i + 1; j < nodes.length; j++) {
        const a = nodes[i];
        const b = nodes[j];
        let dx = a.x - b.x;
        let dy = a.y - b.y;
        let distSq = dx * dx + dy * dy;
        if (distSq < 1) distSq = 1;
        const dist = Math.sqrt(distSq);
        const force = REPULSION / distSq;
        const fx = (dx / dist) * force;
        const fy = (dy / dist) * force;
        a.fx += fx;
        a.fy += fy;
        b.fx -= fx;
        b.fy -= fy;
      }
    }
    for (const e of visibleEdges) {
      const a = e.s;
      const b = e.t;
      let dx = b.x - a.x;
      let dy = b.y - a.y;
      let dist = Math.sqrt(dx * dx + dy * dy) || 0.01;
      const ideal = idealLength(e.r);
      const force = SPRING_K * (dist - ideal);
      const fx = (dx / dist) * force;
      const fy = (dy / dist) * force;
      a.fx += fx;
      a.fy += fy;
      b.fx -= fx;
      b.fy -= fy;
    }
    let kinetic = 0;
    for (const n of nodes) {
      if (n.dragging) {
        // Pinned to the pointer by the drag handler -- don't let force
        // integration fight the user's grip. Other nodes still react to
        // its (pointer-driven) position via the repulsion/spring loops
        // above, which read n.x/n.y before this branch runs.
        n.vx = 0;
        n.vy = 0;
        continue;
      }
      n.fx += (cx - n.x) * CENTER_K;
      n.fy += (cy - n.y) * CENTER_K;
      n.vx = (n.vx + n.fx) * DAMPING;
      n.vy = (n.vy + n.fy) * DAMPING;
      n.x += n.vx;
      n.y += n.vy;
      n.x = Math.min(W - MARGIN, Math.max(MARGIN, n.x));
      n.y = Math.min(H - MARGIN, Math.max(MARGIN, n.y));
      kinetic += n.vx * n.vx + n.vy * n.vy;
    }
    return kinetic;
  }

  // ---- dragging --------------------------------------------------------
  // Converts a pointer event's screen (client) coordinates into the SVG's
  // own viewBox user-space coordinates, since the SVG scales responsively
  // (width:100%, height:auto) and its on-screen size rarely matches the
  // 900x560 viewBox.
  let draggingNode = null;
  function toSvgPoint(evt) {
    const ctm = svg.getScreenCTM();
    if (!ctm) return { x: evt.clientX, y: evt.clientY };
    const pt = svg.createSVGPoint();
    pt.x = evt.clientX;
    pt.y = evt.clientY;
    const p = pt.matrixTransform(ctm.inverse());
    return { x: p.x, y: p.y };
  }
  function startDrag(n, evt) {
    evt.preventDefault();
    draggingNode = n;
    n.dragging = true;
    n.vx = 0;
    n.vy = 0;
    n._dom.style.cursor = "grabbing";
    try {
      n._dom.setPointerCapture(evt.pointerId);
    } catch (err) {
      /* ignore -- unsupported in some test environments */
    }
    hideTooltip();
    ensureRunning();
  }
  function dragMove(n, evt) {
    if (draggingNode !== n) return;
    const p = toSvgPoint(evt);
    n.x = Math.min(W - MARGIN, Math.max(MARGIN, p.x));
    n.y = Math.min(H - MARGIN, Math.max(MARGIN, p.y));
    n.vx = 0;
    n.vy = 0;
    ensureRunning();
  }
  function endDrag(n, evt) {
    if (draggingNode !== n) return;
    n.dragging = false;
    draggingNode = null;
    n._dom.style.cursor = "grab";
    try {
      n._dom.releasePointerCapture(evt.pointerId);
    } catch (err) {
      /* ignore */
    }
  }

  // ---- rendering -----------------------------------------------------
  const NODE_R = 12;

  function buildStaticDom() {
    edgesLayer.innerHTML = "";
    nodesLayer.innerHTML = "";
    labelsLayer.innerHTML = "";

    for (const e of visibleEdges) {
      const line = document.createElementNS(svgNS, "line");
      const positive = e.r >= 0;
      line.setAttribute("stroke", positive ? EDGE_COLOR.pos : EDGE_COLOR.neg);
      line.setAttribute("stroke-width", edgeWidth(e.r));
      line.setAttribute("stroke-linecap", "round");
      line.setAttribute("opacity", 0.75);
      if (!positive) line.setAttribute("stroke-dasharray", "5,4");
      line.style.cursor = "pointer";
      line.addEventListener("mousemove", (evt) => {
        showTooltip(
          `<b>${e.source}</b> ↔ <b>${e.target}</b><br>r = ${e.r.toFixed(3)}`,
          evt.clientX,
          evt.clientY
        );
      });
      line.addEventListener("mouseleave", hideTooltip);
      edgesLayer.appendChild(line);
      e._dom = line;
    }

    for (const n of nodes) {
      const circle = document.createElementNS(svgNS, "circle");
      circle.setAttribute("r", NODE_R);
      circle.setAttribute("fill", dictColor(n.dict));
      circle.setAttribute("stroke", isDark() ? "#ffffff" : "#000000");
      circle.setAttribute("stroke-width", 1.5);
      circle.style.cursor = "grab";
      circle.style.touchAction = "none"; // let us handle drag instead of the browser scrolling
      circle.addEventListener("mousemove", (evt) => {
        if (draggingNode) return;
        showTooltip(
          `<b>${n.term}</b><br>${DICT_LABEL[n.dict]} (${n.dir})<br>Peak F1: ${n.f1_mean.toFixed(3)} · layer ${n.layer}`,
          evt.clientX,
          evt.clientY
        );
      });
      circle.addEventListener("mouseleave", () => {
        if (!draggingNode) hideTooltip();
      });
      circle.addEventListener("pointerdown", (evt) => startDrag(n, evt));
      circle.addEventListener("pointermove", (evt) => dragMove(n, evt));
      circle.addEventListener("pointerup", (evt) => endDrag(n, evt));
      circle.addEventListener("pointercancel", (evt) => endDrag(n, evt));
      nodesLayer.appendChild(circle);
      n._dom = circle;

      const g = document.createElementNS(svgNS, "g");
      const rect = document.createElementNS(svgNS, "rect");
      const text = document.createElementNS(svgNS, "text");
      text.setAttribute("font-family", cssVar("--font-sans"));
      text.setAttribute("font-size", "12");
      text.setAttribute("font-weight", "600");
      text.setAttribute("fill", cssVar("--color-ink"));
      text.setAttribute("text-anchor", "middle");
      text.textContent = n.term;
      const boxW = n.term.length * 6.4 + 10;
      rect.setAttribute("width", boxW);
      rect.setAttribute("height", 17);
      rect.setAttribute("rx", 3);
      rect.setAttribute("fill", cssVar("--color-bg"));
      rect.setAttribute("opacity", 0.88);
      rect.setAttribute("stroke", cssVar("--color-border"));
      g.appendChild(rect);
      g.appendChild(text);
      labelsLayer.appendChild(g);
      n._labelDom = g;
      n._labelRect = rect;
      n._labelText = text;
      n._labelBoxW = boxW;
    }
  }

  function render() {
    for (const e of visibleEdges) {
      e._dom.setAttribute("x1", e.s.x);
      e._dom.setAttribute("y1", e.s.y);
      e._dom.setAttribute("x2", e.t.x);
      e._dom.setAttribute("y2", e.t.y);
    }
    for (const n of nodes) {
      n._dom.setAttribute("cx", n.x);
      n._dom.setAttribute("cy", n.y);
      const lx = n.x - n._labelBoxW / 2;
      const ly = n.y + NODE_R + 4;
      n._labelRect.setAttribute("x", lx);
      n._labelRect.setAttribute("y", ly);
      n._labelText.setAttribute("x", n.x);
      n._labelText.setAttribute("y", ly + 12.5);
    }
  }

  let rafId = null;
  function loop() {
    const kinetic = tick();
    render();
    // Keep animating while a node is actively being dragged, even if the
    // rest of the layout has otherwise settled below the kinetic epsilon --
    // otherwise a drag on a settled graph would render only on the next
    // pointermove tick instead of continuously.
    if (kinetic > 0.02 || draggingNode) {
      rafId = requestAnimationFrame(loop);
    } else {
      rafId = null;
    }
  }
  function ensureRunning() {
    if (rafId === null) rafId = requestAnimationFrame(loop);
  }

  buildStaticDom();
  render();
  ensureRunning();

  // Re-render (colors depend on cssVar) when the site's dark-mode toggle
  // flips; rebuild the DOM since node/edge colors are baked into
  // attributes at construction time here, not read live.
  const observer = new MutationObserver(() => {
    buildStaticDom();
    render();
    ensureRunning();
  });
  observer.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });

  let resizeTimer = null;
  window.addEventListener("resize", () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(ensureRunning, 150);
  });
})();
